      SUBROUTINE PARSECCC     CALCULATES PARTIALS OF SECOND-ORDER MATRIX OF A SINGLEC     BEAM ELEMENT WITH RESPECT TO THE VARIED QUANTITYCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'T.CIN'CC---------------------------------------------------------------      IF (TYPEC .EQ. 2) GO TO 200      IF (TYPEC .EQ. 3) GO TO 300      IF (TYPEC .EQ. 4) GO TO 400      IF (TYPEC .EQ. 5) GO TO 500      IF (TYPEC .EQ. 18) GO TO 1800      IF (TYPEC .EQ. 19) GO TO 1900      IF (TYPEC .EQ. 25) GO TO 5000      IF (TYPEC .EQ. 35) GO TO 3500      IF (TYPEC .EQ. 36) GO TO 3500      RETURNCC     2. -- POLE FACE ROTATIONC  200 IF (TYPE .EQ. 2 .AND. JV .EQ. 4) GO TO 210      IF ((TYPE .EQ. 28 .OR. TYPE .EQ. 29) .AND.     1    (JV .EQ. 18 .OR. JV .EQ. 19)) GO TO 210      GO TO 5000C  210 IF (SOFA) LINEAR = .FALSE.      EPS = 2.0*H0*APB(2)      TB2 = TB*TB      SB2 = SB*SB      SB3 = SB2*SB      TV(2,1) = 0.5*H0*SB3/UNITI(8)      TV(2,6) = - 0.5*H0*(SB3 - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))/     1          UNITI(8)      TV(4,4) = - H0*(SB3 - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))/UNITI(8)      GO TO 5000CC     3. -- DRIFT SPACEC  300 LV = DPARM*UNITI(8)      TV(5,3) = - 0.5*LV      TV(5,10) = - 0.5*LV      GO TO 5000CC     4. -- BENDING MAGNETC  400 CALL DBEND2      GO TO 5000CC     5. -- QUADRUPOLEC  500 IF (JV .EQ. 2 .OR. JV .EQ. 4 .OR. JV .EQ. 5) GO TO 520      JQUAD = 1      KQ2 = KX2      CALL DFOL2      JQUAD = 3      KQ2 = KY2      CALL DFOL2      GO TO 5000C  520 JQUAD = 1      KQ2 = KX2      CALL DFOCU2      JQUAD = 3      KQ2 = KY2      KVK = - KVK      CALL DFOCU2      KVK = - KVK      GO TO 5000CC     18. -- SEXTUPOLEC 1800 IF (SOFA) LINEAR = .FALSE.      CALL DSEXT2      GO TO 5000CC     19. -- SOLENOIDC 1900 IF (SOFA) LINEAR = .FALSE.      CALL DSOLE2      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 CONTINUE      GO TO 5000CC     CHANGE TRIANGULAR MATRIX INTO SQUARE MATRIXC 5000 IF (NORD1 .GE. 3) CALL PARTRJ      RETURN      END